CONCURRENCY = 50  # peticiones simultáneas máximas

def clean(text):
    return text.split("/")[0].split("[")[0]

async def fetch_char(session, semaphore, char):
    async with semaphore:
        url = f"https://hanzicraft.com/api/character/{char}"
        async with session.get(url) as resp:
            data = await resp.json(content_type=None)

    examplewords = data["examplewords"][char]
    wordcount = data["wordcounts"][char]
    frequency = data["frequencyContributions"][char]

    rows = []
    for i, group in enumerate(examplewords[:3]):
        for entry in group:
            rows.append({
                "hanzi": char,
                "simplified": entry.get("simplified"),
                "definition": clean(entry.get("definition", "")),
                "group": i + 1,
                "wordcount": wordcount,
                "frequency_contribution": frequency,
            })
    return rows

async def main():
    semaphore = asyncio.Semaphore(CONCURRENCY)
    connector = aiohttp.TCPConnector(limit=CONCURRENCY)

    async with aiohttp.ClientSession(connector=connector) as session:
        tasks = [fetch_char(session, semaphore, char) for char in chars]
        results = await asyncio.gather(*tasks, return_exceptions=True)

    all_rows = []
    errors = []
    for char, result in zip(chars, results):
        if isinstance(result, Exception):
            errors.append((char, result))
        else:
            all_rows.extend(result)

    if errors:
        print(f"⚠️  {len(errors)} errores:")
        for char, err in errors:
            print(f"  {char}: {err}")

    df = pd.DataFrame(all_rows, columns=[
        "hanzi", "simplified", "definition", "group",
        "wordcount", "frequency_contribution"
    ])

    script_dir = os.path.dirname(os.path.abspath(__file__))
    output_path = os.path.join(script_dir, "hanzi_examples.xlsx")
    df.to_excel(output_path, index=False)
    print(f"✅ Archivo guardado en: {output_path} ({len(df)} filas)")

if __name__ == "__main__":
    asyncio.run(main())